    if (label.includes('rumiación') || label.includes('culpa')) return nodeEnrichment['n16'].src;
    if (label.includes('corte') || label.includes('pelo') || label.includes('cabello') || label.includes('tumbado')) return nodeEnrichment['n5'].src;
